mapper.sql:
SELECT inv.id, sku.id AS sku_id, sku.sku_no, sku.sku_name, sku.unit_price, item.id AS item_id, item.item_name, item.item_no, w.id AS warehouse_id, w.warehouse_name, inv.storage_shelf, inv.quantity, inv.remark FROM wms_inventory inv INNER JOIN ( SELECT sku_id, warehouse_id FROM wms_inventory GROUP BY sku_id, warehouse_id
HAVING SUM(quantity) <= #{dto.maxQuantity}
) warn ON inv.sku_id = warn.sku_id AND inv.warehouse_id = warn.warehouse_id INNER JOIN wms_item_sku sku ON inv.sku_id = sku.id INNER JOIN wms_item item ON sku.item_id = item.id INNER JOIN wms_warehouse w ON inv.warehouse_id = w.id
AND inv.warehouse_id = #{dto.warehouseId}
AND item.item_name LIKE CONCAT('%', #{dto.itemName}, '%')
AND item.item_no LIKE CONCAT('%', #{dto.itemNo}, '%')
AND sku.sku_name LIKE CONCAT('%', #{dto.skuName}, '%')
AND sku.sku_no LIKE CONCAT('%', #{dto.skuNo}, '%')

mapper.update:
UPDATE wms_inventory
SET quantity = quantity - #{quantity}
WHERE warehouse_id = #{warehouseId}
  AND sku_id = #{skuId}
  AND quantity >= #{quantity}


    AND (storage_shelf IS NULL OR storage_shelf = '')



    AND storage_shelf = #{storageShelf}
